'use client';

import Link from 'next/link';
import { AssignmentInd as AssignmentIndIcon, AutoAwesome as AutoAwesomeIcon } from '@mui/icons-material'; // Icônes modernes
import Sidebar from "../../components/sidebar";  
import Navbar from "../../components/Navbar";    

export default function ListGroupe() {
  return (
    <div className="flex h-screen min-h-screen w-screen bg-gray-50">
      {/* Sidebar and Navbar layout */}
      <Sidebar className="h-screen hidden lg:block" /> 
      <div className="w-full flex flex-col h-screen">
        <Navbar />

        {/* Titre de la page */}
        <div className="text-center mt-10">
          <h1 className="text-4xl font-bold text-blue-700">Affectation tuteur et sujet</h1>
        </div>

        {/* Section avec les cartes centrées */}
        <div className="flex flex-col items-center justify-center flex-1">
          <div className="flex space-x-14">

            {/* Carte pour affectation manuelle */}
            <Link href="/affectation">
              <div className="flex flex-col items-center bg-white border border-gray-200 rounded-2xl p-12 hover:shadow-2xl transition-shadow duration-300 ease-in-out transform hover:scale-105 cursor-pointer w-96 h-96 flex justify-center items-center">
                <div className="bg-blue-100 p-8 rounded-full">
                  <AssignmentIndIcon className="text-blue-600 text-6xl" /> {/* Icône moderne */}
                </div>
                <h2 className="text-xl font-semibold text-gray-800 mt-8">Affectation manuelle</h2>
              </div>
            </Link>

            {/* Carte pour affectation automatique */}
            <Link href="/affectationauto">
              <div className="flex flex-col items-center bg-white border border-gray-200 rounded-2xl p-12 hover:shadow-2xl transition-shadow duration-300 ease-in-out transform hover:scale-105 cursor-pointer w-96 h-96 flex justify-center items-center">
                <div className="bg-blue-100 p-8 rounded-full">
                  <AutoAwesomeIcon className="text-blue-600 text-6xl" /> {/* Icône moderne */}
                </div>
                <h2 className="text-xl font-semibold text-gray-800 mt-8">Affectation automatique</h2>
              </div>
            </Link>

          </div>
        </div>
      </div>
    </div>
  );
}